#!/usr/bin/env python3

"""
========================================================
RoboMaster 哨兵机器人
第19课：基础避障决策
========================================================

本课开始让机器人进行“思考”。

数据来源：

    /scan
      ↓
    LaserScan
      ↓
    前 / 左 / 右 / 后距离
      ↓
    安全判断
      ↓
    避障决策


本课暂时不控制真实底盘。

只输出：

    前进
    左转
    右转
    后退


以后我们会把这里的简单规则逐渐升级成真正的
RoboMaster 哨兵决策系统。

========================================================
"""

# ========================================================
# 1. 导入 ROS2
# ========================================================

import rclpy

from rclpy.node import Node


# ========================================================
# 2. 导入 LaserScan
# ========================================================

from sensor_msgs.msg import LaserScan


# ========================================================
# 3. 数学库
# ========================================================

import math


# ========================================================
# 4. 安全距离
# ========================================================

SAFE_DISTANCE = 1.0


# ========================================================
# 5. 创建决策节点
# ========================================================

class ObstacleDecision(Node):

    def __init__(self):

        # 创建 ROS2 节点

        super().__init__(
            "lesson19_obstacle_decision"
        )


        # =================================================
        # 创建 Subscriber
        # =================================================

        self.subscription = self.create_subscription(

            LaserScan,

            "/scan",

            self.scan_callback,

            10
        )


        self.get_logger().info(

            "第19课：基础避障决策节点已经启动"
        )


    # ====================================================
    # /scan 回调函数
    # ====================================================

    def scan_callback(self, scan):

        """
        接收到雷达数据后：

            1. 计算四个方向最近距离
            2. 判断前方是否危险
            3. 决定运动方向
        """


        # =================================================
        # 初始化距离
        # =================================================

        front_distance = float("inf")

        left_distance = float("inf")

        right_distance = float("inf")

        back_distance = float("inf")


        # =================================================
        # 遍历雷达数据
        # =================================================

        for i, distance in enumerate(scan.ranges):


            # ------------------------------------------------
            # 忽略无效数据
            # ------------------------------------------------

            if not math.isfinite(distance):

                continue


            # ------------------------------------------------
            # 忽略非法距离
            # ------------------------------------------------

            if distance < scan.range_min:

                continue


            if distance > scan.range_max:

                continue


            # ------------------------------------------------
            # 计算角度
            # ------------------------------------------------

            angle = (

                scan.angle_min

                + i * scan.angle_increment
            )


            angle_degree = math.degrees(angle)


            # =================================================
            # 前方
            # =================================================

            if -45.0 <= angle_degree <= 45.0:

                if distance < front_distance:

                    front_distance = distance


            # =================================================
            # 左方
            # =================================================

            elif 45.0 < angle_degree <= 135.0:

                if distance < left_distance:

                    left_distance = distance


            # =================================================
            # 右方
            # =================================================

            elif -135.0 <= angle_degree < -45.0:

                if distance < right_distance:

                    right_distance = distance


            # =================================================
            # 后方
            # =================================================

            else:

                if distance < back_distance:

                    back_distance = distance


        # =================================================
        # 开始决策
        # =================================================

        # -------------------------------------------------
        # 情况1：
        #
        # 前方安全
        # -------------------------------------------------

        if front_distance >= SAFE_DISTANCE:

            decision = "前进"


        # -------------------------------------------------
        # 情况2：
        #
        # 前方危险
        #
        # 左边比右边安全
        # -------------------------------------------------

        elif left_distance > right_distance:

            decision = "左转"


        # -------------------------------------------------
        # 情况3：
        #
        # 前方危险
        #
        # 右边比左边安全
        # -------------------------------------------------

        elif right_distance > left_distance:

            decision = "右转"


        # -------------------------------------------------
        # 情况4：
        #
        # 两边都不安全
        # -------------------------------------------------

        else:

            decision = "后退"


        # =================================================
        # 输出环境信息
        # =================================================

        self.get_logger().info(

            f"前={front_distance:.2f}m | "
            f"左={left_distance:.2f}m | "
            f"右={right_distance:.2f}m | "
            f"后={back_distance:.2f}m"
        )


        # =================================================
        # 输出决策
        # =================================================

        self.get_logger().info(

            f"机器人决策：{decision}"
        )


# ========================================================
# main
# ========================================================

def main(args=None):

    # 初始化 ROS2

    rclpy.init(args=args)


    # 创建节点

    node = ObstacleDecision()


    try:

        # 持续运行

        rclpy.spin(node)


    except KeyboardInterrupt:

        pass


    # 销毁节点

    node.destroy_node()


    # 关闭 ROS2

    rclpy.shutdown()


# ========================================================
# 程序入口
# ========================================================

if __name__ == "__main__":

    main()